using System.Security.Claims; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using PersonalFinanceManager.Data; using PersonalFinanceManager.Models;
namespace PersonalFinanceManager.Controllers;
[Authorize] public class GoalsController(ApplicationDbContext context):Controller { private string UserId=>User.FindFirstValue(ClaimTypes.NameIdentifier)!; public async Task<IActionResult> Index(){UserDataOwnership.EnsureUserData(context,UserId);return View(await context.FinancialGoals.Where(x=>x.UserId==UserId).OrderBy(x=>x.TargetDate).ToListAsync());} public IActionResult Create()=>View(new FinancialGoal()); [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(FinancialGoal goal){if(!ModelState.IsValid)return View(goal);goal.UserId=UserId;context.FinancialGoals.Add(goal);await context.SaveChangesAsync();return RedirectToAction(nameof(Index));} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Contribute(int id,decimal amount){var goal=await context.FinancialGoals.FirstOrDefaultAsync(x=>x.Id==id&&x.UserId==UserId);if(goal is not null&&amount>0){goal.CurrentAmount=Math.Min(goal.TargetAmount,goal.CurrentAmount+amount);await context.SaveChangesAsync();}return RedirectToAction(nameof(Index));} }
